def _codec72_need(ok, reason):
    if not ok:
        raise ValueError(reason)


def _codec72_sha(raw):
    return _codec72_hashlib.sha256(raw).hexdigest()


def _codec72_bare(raw):
    _codec72_need(type(raw) is bytes, 'codec72 byte original required')
    return {'bytes': len(raw), 'sha256': _codec72_sha(raw)}


def _codec72_pretty(value):
    return (_codec72_json.dumps(value, sort_keys=True, indent=2, ensure_ascii=False, allow_nan=False) + '\n').encode('utf-8')


def _codec72_compact(value):
    return (_codec72_json.dumps(value, sort_keys=True, separators=(',', ':'), ensure_ascii=False, allow_nan=False) + '\n').encode('utf-8')


def _codec72_strict(raw):
    _codec72_need(type(raw) is bytes, 'codec72 strict JSON bytes required')
    def pairs(items):
        value = {}
        for key, item in items:
            _codec72_need(key not in value, 'codec72 duplicate JSON key')
            value[key] = item
        return value
    return _codec72_json.loads(raw.decode('utf-8', 'strict'), object_pairs_hook=pairs,
        parse_constant=lambda _: (_ for _ in ()).throw(ValueError('codec72 nonfinite JSON')))


def _codec72_pin(raw, pin, reason):
    _codec72_need(type(pin) is dict and set(pin) == {'bytes', 'sha256'}
                  and type(pin['bytes']) is int and pin['bytes'] >= 0
                  and _codec72_bare(raw) == pin, 'codec72 exact pin differs: ' + reason)
    return raw


def _codec72_inverse(raw, replacements, reason):
    for row in reversed(replacements):
        old, new = row['old_utf8'].encode('utf-8'), row['new_utf8'].encode('utf-8')
        _codec72_need(raw.count(new) == 1, 'codec72 inverse anchor differs: ' + reason)
        raw = raw.replace(new, old)
    return raw


def _codec72_restore_shared(shared_files):
    _codec72_need(type(shared_files) is dict and len(shared_files) == 17
                  and set(shared_files) == {r['path'] for r in CODEC72_SHARED_ROWS},
                  'codec72 full shared17 byte map required')
    for row in CODEC72_SHARED_ROWS:
        _codec72_pin(shared_files[row['path']], {k: row[k] for k in ('bytes', 'sha256')}, row['path'])
    _codec72_need(sum(map(len, shared_files.values())) <= 16*1024*1024,
                  'codec72 shared original bytes exceed existing original budget')
    parent = dict(shared_files)
    mapper_key = 'provider/source/phone_observation_tools.py'
    daily_key = 'provider/source/daily_phone_local.py'
    parent[mapper_key] = _codec72_inverse(parent[mapper_key], [CODEC72_MAPPER_INVERSE], 'mapper')
    _codec72_pin(parent[mapper_key], {'bytes': 38774, 'sha256': 'f16c77c1b4509babcea5fc2e8d0a7ae8ab43b3cd58e6640441b44ecd4bccb6df'}, 'original mapper')
    new_pin = b'8f60cfd359ccfa269fabb05b616371268a2b86938fc41da37a2111c10066b792'
    old_pin = b'f16c77c1b4509babcea5fc2e8d0a7ae8ab43b3cd58e6640441b44ecd4bccb6df'
    _codec72_need(parent[daily_key].count(new_pin) == 1, 'codec72 daily sole mapper pin differs')
    parent[daily_key] = parent[daily_key].replace(new_pin, old_pin)
    _codec72_pin(parent[daily_key], {'bytes': 22059, 'sha256': 'f42fa1f3268d2a2c00e49610d356b440d1e32722fbe2af877580fb6eb180f712'}, 'original daily')
    service_key = 'PHONE-SERVICE-INPUTS-v150-r10-r1.json'
    config_key = 'local-config-r10-r1.json'
    service = _codec72_strict(parent[service_key])
    _codec72_need(len(service['provider_sources']) == 15, 'codec72 service source count differs')
    for row in service['provider_sources']:
        _codec72_need(row['path'].startswith('provider-r10-r1/source/'), 'codec72 provider source path differs')
        name = row['path'].split('/')[-1]
        key = 'provider/source/' + name
        _codec72_need(key in parent and row['path'] == 'provider-r10-r1/source/' + name, 'codec72 service source missing')
        row.update(_codec72_bare(parent[key]))
    parent[service_key] = _codec72_pretty(service)
    _codec72_pin(parent[service_key], {'bytes': 10635, 'sha256': '2739a0af53650363e065bb71a448481998c68fc8b8632e61262c319dae6b586a'}, 'original service')
    config = _codec72_strict(parent[config_key])
    config['service_manifest_sha256'] = _codec72_sha(parent[service_key])
    parent[config_key] = _codec72_pretty(config)
    _codec72_pin(parent[config_key], {'bytes': 1493, 'sha256': '780754928709871d3e70f432acb6a021c6c97ab822aaf7c32c887c132cac8c34'}, 'original configuration')
    return parent


def _codec72_verify_and_restore(runtime_raw, source_files, combination_raw, shared_files):
    _codec72_pin(runtime_raw, CODEC72_RUNTIME_PIN, 'new runtime manifest')
    _codec72_need(len(runtime_raw) <= 262144, 'codec72 existing manifest budget exceeded')
    manifest = _codec72_strict(runtime_raw)
    _codec72_need(type(manifest.get('codec72_source_increment')) is dict
                  and _codec72_pretty(manifest['codec72_source_increment']) == _codec72_pretty(CODEC72_INCREMENT),
                  'codec72 exact typed source increment differs')
    rows = manifest['files']
    _codec72_need(type(rows) is list and len(rows) == 32 and type(source_files) is dict
                  and len(source_files) == 32 and {r['path'] for r in rows} == set(source_files),
                  'codec72 full runtime32 byte map required')
    for row in rows:
        _codec72_need(set(row) == {'path', 'bytes', 'sha256'}, 'codec72 exact runtime row differs')
        _codec72_pin(source_files[row['path']], {k: row[k] for k in ('bytes', 'sha256')}, row['path'])
    _codec72_need(sum(map(len, source_files.values())) <= 16*1024*1024,
                  'codec72 runtime original bytes exceed existing original budget')
    _codec72_pin(combination_raw, CODEC72_COMBINATION_PIN, 'new component combination')
    combination = _codec72_strict(combination_raw)
    old_shared = _codec72_restore_shared(shared_files)
    new_sources = {name.split('/')[-1]: raw for name, raw in shared_files.items() if name.startswith('provider/source/')}
    old_sources = {name.split('/')[-1]: raw for name, raw in old_shared.items() if name.startswith('provider/source/')}
    _codec72_need(len(new_sources) == len(old_sources) == 15, 'codec72 source15 topology differs')
    pins = _codec72_pretty({name: _codec72_sha(raw) for name, raw in sorted(new_sources.items())})
    _codec72_need(source_files['reference/REVIEWED-PRODUCTION-PINS.json'] == pins,
                  'codec72 runtime15 pins do not bind the actual shared production')
    config_raw = shared_files['local-config-r10-r1.json']
    service_raw = shared_files['PHONE-SERVICE-INPUTS-v150-r10-r1.json']
    source_seal = {'schema': 'hepta.native-guard.component-source-seal.v150.r10.1',
        'state': 'REVIEWED_COMPONENT_BYTES_NOT_FINAL_RELEASE', 'intended_module_release': 'v150-r10-r1',
        'configuration': _codec72_bare(config_raw), 'phone_service_inputs_sha256': _codec72_sha(service_raw),
        'production_files': [dict(path='source/' + name, **_codec72_bare(raw)) for name, raw in sorted(new_sources.items())]}
    computed = _codec72_copy.deepcopy(CODEC72_PARENT_COMBINATION)
    computed.update(source_seal=_codec72_bare(_codec72_compact(source_seal)),
        configuration=_codec72_bare(config_raw), service_inputs=_codec72_bare(service_raw),
        production_files=[dict(path='production/' + name, **_codec72_bare(raw)) for name, raw in sorted(new_sources.items())])
    _codec72_need(_codec72_compact(computed) == combination_raw
                  and combination['live_policy_sha256'] == 'f8219f9c3ad2e1d16a95fda8d5f0bc7612a31e00c0a661e53bf9a6e921c49d70',
                  'codec72 exact seal/config/service/production/policy combination differs')
    parent_combination_raw = _codec72_compact(CODEC72_PARENT_COMBINATION)
    _codec72_pin(parent_combination_raw, {'bytes': 4702, 'sha256': '54b1d9aef4c16ebc0989b3e13345238bfbd4e400e5bfc9a97e27648a2385057e'}, 'original component combination')
    parent_files = dict(source_files)
    parent_files['source/late_boundary.py'] = _codec72_inverse(parent_files['source/late_boundary.py'], CODEC72_LATE_INVERSE, 'late source')
    parent_files['source/close_component.py'] = _codec72_inverse(parent_files['source/close_component.py'], [CODEC72_CLOSER_INVERSE], 'closer source')
    parent_files['reference/REVIEWED-PRODUCTION-PINS.json'] = _codec72_pretty({name: _codec72_sha(raw) for name, raw in sorted(old_sources.items())})
    parent_manifest = _codec72_copy.deepcopy(manifest)
    parent_manifest.pop('codec72_source_increment')
    parent_manifest['current_combination_sha256'] = _codec72_sha(parent_combination_raw)
    parent_manifest['reviewed_production_pins_sha256'] = _codec72_sha(parent_files['reference/REVIEWED-PRODUCTION-PINS.json'])
    parent_manifest['files'] = [dict(path=row['path'], **_codec72_bare(parent_files[row['path']])) for row in rows]
    parent_runtime_raw = _codec72_pretty(parent_manifest)
    _codec72_pin(parent_runtime_raw, CODEC72_PARENT_RUNTIME_PIN, 'whole runtime inverse to actual31da')
    changes = [name for name in source_files if source_files[name] != parent_files[name]]
    _codec72_need(set(changes) == {'reference/REVIEWED-PRODUCTION-PINS.json', 'source/late_boundary.py', 'source/close_component.py'},
                  'codec72 runtime source delta differs from three reviewed members')
    return manifest, parent_runtime_raw, parent_manifest, parent_files, parent_combination_raw, old_shared


def verify_codec72_runtime_increment(runtime_raw, source_files, combination_raw, shared_files):
    """Reject every other byte generation before any package module is executed."""
    manifest, parent_raw, _parent, _files, parent_combo, _shared = _codec72_verify_and_restore(
        runtime_raw, source_files, combination_raw, shared_files)
    return {'schema': 'hepta.native-guard.codec72-runtime-increment-verification.v1',
        'state': 'EXACT_SOURCE_INCREMENT_VERIFIED_NO_CASE_OR_LIVE_ADMISSION',
        'runtime': _codec72_bare(runtime_raw), 'combination': _codec72_bare(combination_raw),
        'parent_runtime': _codec72_bare(parent_raw), 'parent_combination': _codec72_bare(parent_combo),
        'runtime_source_count': 32, 'unchanged_parent_runtime_members': 29,
        'shared_material_count': 17, 'production_source_count': 15,
        'codec_parent_boundary': manifest['codec72_source_increment']['previous_native_record']['boundary'],
        'whole_manifest_and_source_inverses_verified': True,
        'whole_production_service_config_combination_inverses_verified': True,
        'source_execution_performed': False, 'live_originals_read': False,
        'root02_prelaunch_admission_verified_here': False,
        'current_head_admission_verified_here': False,
        'phone_calls': 0, 'nonces_generated': 0, 'component_qualified': False, 'business_qualified': False}


def _codec72_base_late_bytes(parent_raw):
    """Recover exact c50a bytes from actual396d as data, without executing either.

    This is one reviewed contiguous byte-range recipe, not a general patch or
    source-normalization API. Both complete input and output identities bind it.
    """
    packet = CODEC72_BASE67_LATE
    _codec72_need(type(packet) is dict and set(packet) == {
        'schema', 'parent', 'result', 'operations'} and packet['schema'] ==
        'hepta.codec72.exact-historical-byte-inverse.v1', 'codec72 historical inverse packet differs')
    _codec72_pin(parent_raw, packet['parent'], 'actual396d complete source before historical inverse')
    _codec72_need(packet['parent'] == {'bytes': 74287, 'sha256':
        '396da713d4b7cab45d0eda80b65df82d7b570440a9c9ea1f74f342b81031ec97'}
        and type(packet['result']) is dict and set(packet['result']) == {'bytes', 'sha256'}
        and type(packet['result']['bytes']) is int and packet['result'] == {'bytes': 66996, 'sha256':
        'c50a219efd992ce1353494ace2656af20c932cbc32530b0085e38a79975d8add'},
        'codec72 fixed historical input/output identity differs')
    operations = packet['operations']
    _codec72_need(type(operations) is list and len(operations) == 15,
                  'codec72 exact historical operation count differs')
    cursor = 0; result = bytearray()
    for item in operations:
        _codec72_need(type(item) is dict and item.get('kind') in ('copy', 'replace')
            and set(item) == ({'kind', 'start', 'bytes'} if item['kind'] == 'copy' else
                             {'kind', 'start', 'bytes', 'literal_utf8'})
            and type(item['start']) is int and type(item['bytes']) is int
            and item['start'] == cursor and 0 <= item['bytes'] <= len(parent_raw) - cursor,
            'codec72 historical ranges are incomplete, overlapping, reordered or malformed')
        end = cursor + item['bytes']
        if item['kind'] == 'copy':
            _codec72_need(item['bytes'] > 0, 'codec72 empty historical copy range')
            piece = parent_raw[cursor:end]
        else:
            _codec72_need(type(item['literal_utf8']) is str,
                          'codec72 exact historical literal must be UTF-8 text')
            piece = item['literal_utf8'].encode('utf-8', 'strict')
            _codec72_need(len(piece) <= 192, 'codec72 historical literal exceeds fixed recipe budget')
        _codec72_need(len(result) + len(piece) <= 66996,
                      'codec72 historical reconstruction exceeds exact original size')
        result.extend(piece); cursor = end
    _codec72_need(cursor == len(parent_raw), 'codec72 historical inverse did not consume the complete source')
    return _codec72_pin(bytes(result), packet['result'], 'whole inverse to retained c50a proof-only bytes')


def codec72_historical_runtime_view(runtime_raw, source_files, combination_raw, shared_files):
    """Return a historical proof view only after exact admission of actual bytes.

    The caller must retain the actual generation separately for all execution,
    material, manifest, constructor and consumer outputs. The returned67dc/c50a
    bytes establish the unchanged older R7→R8/policy history; they are never
    presented as the current runtime or as the bytes executed by old902.
    """
    _value, _parent_raw, parent, parent_files, parent_combo, parent_shared = _codec72_verify_and_restore(
        runtime_raw, source_files, combination_raw, shared_files)
    base_late = _codec72_base_late_bytes(parent_files['source/late_boundary.py'])
    base_files = dict(parent_files)
    base_files['source/late_boundary.py'] = base_late
    base = _codec72_copy.deepcopy(parent)
    base['files'] = [dict(path=row['path'], **_codec72_bare(base_files[row['path']])) for row in parent['files']]
    base_raw = _codec72_pretty(base)
    _codec72_pin(base_raw, CODEC72_BASE67_RUNTIME_PIN, 'exact older67dc historical proof manifest')
    return base_raw, base, base_files, parent_combo, parent_shared
